    Idea("standing_order", "The Standing Order", "A garrison executive governs permanently, with a civilian cabinet that advises but does not decide.",
         "stability_factor = 0.06\nwar_stability_factor = 0.1\npolitical_power_gain = 0.1", ("medal", "command")),
