    Idea("plains_dispersal", "A Dispersed Plains", "Stores, clinics and workshops are spread across every district of the plains.",
         "production_speed_buildings_factor = 0.05\nindustrial_capacity_factory = -0.03\nstability_factor = 0.02", ("logistics", "civil")),
