    Idea("open_plains", "Open Plains", "Refugees are settled on the plains and counted as future citizens.",
         "recruitable_population_factor = 0.03\nstability_factor = -0.03\nconsumer_goods_factor = 0.02", ("refugees", "civil")),
    Idea("controlled_passage", "Controlled Passage", "Refugees are fed, treated and escorted onward. Ferustia is a corridor, not a destination.",
         "stability_factor = 0.02\nopinion_gain_monthly_factor = -0.05", ("gate", "refugees")),
    Idea("armed_passes", "Armed Passes", "The mountain approaches are closed to every army and covered by anti-aircraft batteries.",
         "army_core_defence_factor = 0.08\nwar_support_factor = 0.05\nconsumer_goods_factor = 0.02", ("security", "radar")),
    Idea("overflight_arrangement", "The Overflight Arrangement", "ISAF transports and medical flights may cross Ferustian airspace under Ferustian control. Ferustia has not joined the alliance.",
         "experience_gain_air_factor = 0.1\nopinion_gain_monthly_factor = 0.1", ("air", "diplomacy")),
